def compute(vars):
    share_price = vars["Share Price"]
    total_shares_outstanding = vars["Total Shares Outstanding"]
    market_capitalization = share_price * total_shares_outstanding

    return {
        "value": market_capitalization,
        "trace": {
            "Share Price": share_price,
            "Total Shares Outstanding": total_shares_outstanding,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "$"
            }
        }
    }
